#include <omp.h>
#include <vector>
#include <algorithm>

/* Compute the reverse prefix sum of the vector x into output.
   Use OpenMP to compute in parallel.
   Examples:

   input: [1, 7, 4, 6, 6, 2]
   output: [2, 8, 14, 18, 25, 26]

   input: [3, 3, 7, 1, -2]
   output: [-2, -1, 6, 9, 12]
*/
void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    int n = x.size();
    if (n == 0) {
        output.clear();
        return;
    }

    output.resize(n);

    // Reverse prefix sum: output[i] = x[i] + x[i+1] + ... + x[n-1]
    // This is equivalent to: compute prefix sum of reversed array, then reverse back.
    // Or: output[n-1] = x[n-1], output[i] = x[i] + output[i+1]

    // We'll use a parallel approach:
    // 1. Copy x into output
    // 2. Compute reverse prefix sum using a tree-based approach or by reversing, doing forward prefix sum, then reversing back.

    // Approach: Reverse the array, compute forward prefix sum, reverse back.
    // Step 1: Create a reversed copy
    std::vector<int> rev(n);
    #pragma omp parallel for
    for (int i = 0; i < n; i++) {
        rev[i] = x[n - 1 - i];
    }

    // Step 2: Compute forward prefix sum of rev
    // We need to do this carefully in parallel. Use a two-phase approach:
    // Phase 1: Local prefix sums within chunks
    // Phase 2: Global prefix sums using the chunk boundaries

    // For simplicity and correctness, let's use a sequential prefix sum on the reversed array
    // but parallelize the initial copy and final reverse. The prefix sum itself is inherently sequential.
    // However, we can parallelize it using a tree-based approach.

    // Let's implement a parallel prefix sum (scan) on rev.
    // Use inclusive scan.

