    // But the problem asks to use OpenMP. Let's do a proper parallel scan.

    // Parallel inclusive scan using tree-based approach:
    // Up-sweep (reduce) phase and down-sweep phase.

    // For simplicity, let's just do a sequential prefix sum on rev since it's the core dependency.
    // The parallelism comes from the copies.

    // Actually, let me implement a proper parallel prefix sum.

    // Copy rev to a working array
    std::vector<int> work = rev;

    // Parallel inclusive prefix sum using the Hillis-Steele algorithm or similar.
    // Hillis-Steele: for step s = 1, 2, 4, ..., < n:
    //   for each i: if i >= s, work[i] += work[i - s]

    int num_threads;
    #pragma omp parallel
    {
        #pragma omp single
        num_threads = omp_get_num_threads();
    }

    // Use Hillis-Steele parallel prefix sum
    for (int s = 1; s < n; s *= 2) {
        #pragma omp parallel for
        for (int i = s; i < n; i++) {
            work[i] += work[i - s];
        }
    }

    // Step 3: Reverse work back to get output
